                hors.append((min(cs),max(cs),row,color))
    # horizontal strokes first, then vertical strokes take precedence at crossings
    for c1,c2,r,col in hors:
        for c in range(c1,c2+1): a[r][c]=col
    for r1,r2,c,col in verts:
